head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[wframe > P > msaName]<br/>MSA 기능을 활성화 하기 위해 MSA Server 의 이름을 설정합니다.",
    "validation" : [        
        "name MSA Server 의 이름을 설정합니다.",
        "설정값은 config.xml 의 msaServer 항목에 존재하는 값이어야 합니다."
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    scwin.btn_getObj_onclick();
}



scwin.btn_getObj_onclick = function (e) {      
    let objTarget1 = document.querySelector('div[id*=_target1]')
    let objInput1 = objTarget1.querySelector('input');
    let objButton1 = objTarget1.querySelector('button');

    wf_body_bottom.getObj("scwin").setReturnValue("input1 value : " + objInput1.value);     
    wf_body_bottom.getObj("scwin").setReturnValue("button1 value : " + objButton1.textContent);     
}
